import type { MessageTone } from '@vybora/api';
import { isAppLocked } from '@/features/applock/lockState';

// Original tones generated by scripts/generate-tones.mjs (served from /public/tones).
const players = new Map<string, HTMLAudioElement>();

/** Play a message tone in the page. Browsers may block audio until the user has interacted. */
export function playTone(tone: MessageTone) {
  // Silent while the app lock is up: a tone would say a message arrived.
  if (tone === 'none' || typeof Audio === 'undefined' || isAppLocked()) return;
  try {
    let a = players.get(tone);
    if (!a) {
      a = new Audio(`/tones/${tone}.wav`);
      a.volume = 0.6;
      players.set(tone, a);
    }
    a.currentTime = 0;
    void a.play().catch(() => undefined);
  } catch {
    // Audio is a nicety; never break messaging over it.
  }
}
